// Кейс: .qa/tests/emergency/EMG-005.md · план: .qa/e2e-app/specs/app.md (1.2)
// ЗАПРЕЩЕНО нажимать «חיוג ל-101» (настоящий звонок). Тест нажимает только «ביטול» по точному названию.
import { by, assert, APP_BUNDLE_ID } from '../../lib/appium.mjs';
import { onHome } from '../../lib/banci.mjs';

export const name = 'חירום → «חיוג למד״א 101» → окно «לחייג למד״א 101?» → «ביטול», звонка нет #1273694f @iphone @app @prod-safe';

const TITLE = 'לחייג למד״א 101';
const CONFIRM = 'חיוג ל-101'; // только проверка видимости, НЕ нажимать

export default async function (app) {
  // 1. «בית» → «חירום» → экран «עזרה דחופה».
  await onHome(app);
  await app.tap(by.exact('חירום'), { what: 'кнопка «חירום» на בית' });
  const call = await app.waitFor(by.begins('חיוג למד״א 101'), { timeout: 15000, what: 'кнопка «חיוג למד״א 101» на «עזרה דחופה»' });

  // 2. «חיוג למד״א 101» → окно подтверждения.
  await call.click();
  const end = Date.now() + 10000;
  let kind = null, sys = null;
  while (Date.now() < end && !kind) {
    sys = await app.alert();
    if (sys && String(sys.text).includes(TITLE)) kind = 'system';
    else if (await app.exists(by.contains(TITLE))) kind = 'in-app';
    else await new Promise((r) => setTimeout(r, 300));
  }
  assert(kind, `появилось окно «${TITLE}?»`);

  // 3. В окне есть «חיוג ל-101» и «ביטול»; нажать ТОЛЬКО «ביטול».
  if (kind === 'system') {
    assert(sys.buttons.includes(CONFIRM), `в окне есть кнопка «${CONFIRM}» (кнопки: ${sys.buttons.join(' / ')})`);
    assert(sys.buttons.includes('ביטול'), `в окне есть кнопка «ביטול» (кнопки: ${sys.buttons.join(' / ')})`);
    await app.exec('mobile: alert', { action: 'dismiss', buttonLabel: 'ביטול' });
    await app.waitGone(by.contains(TITLE), { what: `окно «${TITLE}?»` });
    assert(!(await app.alert()), 'системное окно закрыто');
  } else {
    assert(await app.exists(by.exact(CONFIRM)), `в окне есть кнопка «${CONFIRM}»`);
    await app.tap(by.exact('ביטול'), { what: 'кнопка «ביטול» в окне' });
    await app.waitGone(by.contains(TITLE), { what: `окно «${TITLE}?»` });
  }

  // 4. Остались в приложении на «עזרה דחופה», звонилка не открывалась.
  assert((await app.appState(APP_BUNDLE_ID)) === 4, 'Banci на переднем плане (звонилка не открыта)');
  assert(await app.exists(by.begins('חיוג למד״א 101')), 'экран «עזרה דחופה» на месте');
}
